private void refresh() {
    // calculate the current progress the bar should start at
    int maxProgress = Math.max(getMax(), 1);
    long periodMillis = _period * 1000L;
    long millisTillRotation = TotpInfo.getMillisTillNextRotation(_period);
    int currentProgress = calcProgress(maxProgress, periodMillis, millisTillRotation);

    // The progress bar is animated in small chunks of (at most) one second, so that it
    // stays in sync with the actual time left till the next rotation. If the period is so
    // long that a single second is worth less than one unit of progress, the length of a
    // chunk is increased to the amount of time it takes to advance the bar by one unit.
    // Not doing so would result in a division by zero and an endless animation loop.
    long millisPerProgressUnit = Math.max(periodMillis / maxProgress, 1);
    long realAnimDuration = Math.min(Math.max(millisPerProgressUnit, ANIM_PART_DURATION), millisTillRotation);
    int animEnd = calcProgress(maxProgress, periodMillis, millisTillRotation - realAnimDuration);

    // start progress animation, compensating for any changes to the animator duration scale settings
    long animDuration = (_animDurationScale > 0) ? (long) (realAnimDuration / _animDurationScale) : 0;
    ObjectAnimator animation = ObjectAnimator.ofInt(this, "progress", currentProgress, animEnd);
    animation.setDuration(animDuration);
    animation.setInterpolator(new LinearInterpolator());
    animation.start();

    // the animation only lasts for the duration of a single chunk, so restart it after that
    _handler.postDelayed(this::refresh, Math.max(realAnimDuration, 1));
}

private static int calcProgress(int maxProgress, long periodMillis, long millisTillRotation) {
    if (periodMillis <= 0) {
        return 0;
    }

    int progress = (int) (maxProgress * ((double) millisTillRotation / periodMillis));
    return Math.max(Math.min(progress, maxProgress), 0);
}

public class TotpProgressBar extends ProgressBar {
    private static final int DEFAULT_PERIOD = 30;

    // the duration (in real milliseconds) of a single chunk of the progress bar animation
    private static final int ANIM_PART_DURATION = 1000;

    private int _period = DEFAULT_PERIOD;

public void setPeriod(int period) {
    // reject periods that can't be rendered (or would cause an endless animation loop)
    _period = TotpInfo.isPeriodValid(period) ? period : DEFAULT_PERIOD;
}

