27	    @Override
28	    public String getOtp() {
29	        try {
30	            OTP otp = TOTP.generateOTP(getSecret(), getAlgorithm(true), getDigits(), getPeriod());
31	            return otp.toString();
32	        } catch (InvalidKeyException | NoSuchAlgorithmException e) {
33	            throw new RuntimeException(e);
34	        }
35	    }
