43	    public JSONObject toJson() {
44	        JSONObject obj = super.toJson();
45	        try {
46	            obj.put("period", getPeriod());
47	        } catch (JSONException e) {
48	            throw new RuntimeException(e);
49	        }
50	        return obj;
51	    }
