57	    public static boolean isPeriodValid(int period) {
58	        if (period <= 0) {
59	            return false;
60	        }
61	
62	        // check for the possibility of an overflow when converting to milliseconds
63	        return period <= Integer.MAX_VALUE / 1000;
64	    }
65	
66	    public void setPeriod(int period) throws OtpInfoException {
67	        if (!isPeriodValid(period)) {
68	            throw new OtpInfoException(String.format("bad period: %d", period));
69	        }
70	        _period = period;
71	    }
72	
73	    public long getMillisTillNextRotation() {
74	        return TotpInfo.getMillisTillNextRotation(_period);
75	    }
76	
77	    public static long getMillisTillNextRotation(int period) {
78	        long p = period * 1000;
79	        return p - (System.currentTimeMillis() % p);
80	    }
