39	        _period = period;
40	    }
41	
42	    public void start() {
43	        stop();
44	        _handler = new Handler();
45	        _animDurationScale = Settings.Global.getFloat(getContext().getContentResolver(), Settings.Global.ANIMATOR_DURATION_SCALE, 1.0f);
46	        refresh();
47	    }
48	
49	    public void stop() {
50	        if (_handler != null) {
51	            _handler.removeCallbacksAndMessages(null);
52	            _handler = null;
53	        }
54	    }
