61	    private void refresh() {
62	        // calculate the current progress the bar should start at
63	        int maxProgress = getMax();
64	        long millisTillRotation = TotpInfo.getMillisTillNextRotation(_period);
65	        int currentProgress = (int) (maxProgress * ((float) millisTillRotation / (_period * 1000)));
66	
67	        // start progress animation, compensating for any changes to the animator duration scale settings
68	        int animPart = maxProgress / _period;
69	        int animEnd = (currentProgress / animPart) * animPart;
70	        int animPartDuration = (int) (1000 / _animDurationScale);
71	        float animDurationFraction = (float) (currentProgress - animEnd) / animPart;
72	        int realAnimDuration =  (int) (1000 * animDurationFraction);
73	        int animDuration =  (int) (animPartDuration * animDurationFraction);
74	        ObjectAnimator animation = ObjectAnimator.ofInt(this, "progress", currentProgress, animEnd);
75	        animation.setDuration(animDuration);
76	        animation.setInterpolator(new LinearInterpolator());
77	        animation.start();
78	
79	        // the animation only lasts for (less than) one second, so restart it after that
80	        _handler.postDelayed(this::refresh, realAnimDuration);
81	    }
82	}
