438	    public int getMostFrequentPeriod() {
439	        List<TotpInfo> infos = new ArrayList<>();
440	        for (VaultEntry entry : _shownEntries) {
441	            OtpInfo info = entry.getInfo();
442	            if (info instanceof TotpInfo) {
443	                infos.add((TotpInfo) info);
444	            }
445	        }
446	
447	        if (infos.isEmpty()) {
448	            return -1;
449	        }
450	
451	        Map<Integer, Integer> occurrences = new HashMap<>();
452	        for (TotpInfo info : infos) {
453	            int period = info.getPeriod();
454	            if(occurrences.containsKey(period)) {
455	                occurrences.put(period, occurrences.get(period) + 1);
456	            } else {
457	                occurrences.put(period, 1);
458	            }
459	        }
460	
461	        Integer maxValue = 0;
462	        Integer maxKey = 0;
463	        for (Map.Entry<Integer, Integer> entry : occurrences.entrySet()){
464	            if(entry.getValue() > maxValue){
465	                maxValue = entry.getValue();
466	                maxKey = entry.getKey();
467	            }
468	        }
469	
470	        return maxValue > 1 ? maxKey : -1;
471	    }
